function countScans(haystack, needles) {
  let steps = 0;
  for (const n of needles) {
    for (const h of haystack) { steps++; if (h === n) break; }
  }
  return steps;
}

const data = [];
for (let i = 0; i < 200; i++) data.push(i);
const queries = [199, 198, 197, 196];

console.log("array scan steps:", countScans(data, queries));

const seen = new Set(data);
let hits = 0;
for (const q of queries) if (seen.has(q)) hits++;
console.log("set lookups:", queries.length, "hits:", hits);

