function makeList() {
  return { nextOf: {}, prevOf: {}, head: null, tail: null };
}

function unlink(list, key) {
  const p = list.prevOf[key], n = list.nextOf[key];
  if (p === null) list.head = n; else list.nextOf[p] = n;
  if (n === null) list.tail = p; else list.prevOf[n] = p;
  delete list.nextOf[key];
  delete list.prevOf[key];
}

function pushFront(list, key) {
  list.prevOf[key] = null;
  list.nextOf[key] = list.head;
  if (list.head !== null) list.prevOf[list.head] = key;
  list.head = key;
  if (list.tail === null) list.tail = key;
}

function order(list) {
  const out = [];
  let at = list.head;
  while (at !== null) { out.push(at); at = list.nextOf[at]; }
  return out;
}

const L = makeList();
pushFront(L, "c"); pushFront(L, "b"); pushFront(L, "a");
console.log(order(L).join(","));
unlink(L, "b");
pushFront(L, "b");
console.log(order(L).join(","), "tail:", L.tail);

