function unlinkKey(nextOf, prevOf, key) {
  const out = {};
  for (const k of Object.keys(nextOf)) {
    if (k !== key) out[k] = nextOf[k];
  }
  if (!(key in nextOf)) return out;
  const p = prevOf[key], n = nextOf[key];
  if (p !== null && p !== undefined) out[p] = n;
  return out;
}

