function makeLRU(capacity) {
  const map = new Map();
  return {
    get(key) {
      if (!map.has(key)) return null;
      const value = map.get(key);
      map.delete(key);
      map.set(key, value);
      return value;
    },
    put(key, value) {
      if (map.has(key)) map.delete(key);
      map.set(key, value);
      if (map.size > capacity) map.delete(map.keys().next().value);
    },
    keys() { return Array.from(map.keys()); }
  };
}

const cache = makeLRU(2);
cache.put("a", 1);
cache.put("b", 2);
console.log(cache.get("a"), cache.keys().join(","));
cache.put("c", 3);
console.log(cache.get("b"), cache.keys().join(","));

