function recencyOrder(accesses) {
  const seen = new Set();
  const out = [];
  for (let i = accesses.length - 1; i >= 0; i--) {
    const k = accesses[i];
    if (!seen.has(k)) { seen.add(k); out.push(k); }
  }
  return out;
}

