function invert(docs) {
  const index = {};
  for (const entry of docs) {
    const id = entry[0];
    for (const t of new Set(entry[1])) {
      if (!index[t]) index[t] = [];
      index[t].push(id);
    }
  }
  for (const t of Object.keys(index)) index[t].sort((a, b) => a - b);
  return index;
}

function andQuery(index, a, b) {
  const x = index[a] || [], y = index[b] || [];
  const out = [];
  let i = 0, j = 0;
  while (i < x.length && j < y.length) {
    if (x[i] === y[j]) { out.push(x[i]); i++; j++; }
    else if (x[i] < y[j]) i++;
    else j++;
  }
  return out;
}

const docs = [[1, ["red", "kite"]], [2, ["red", "boat"]], [3, ["kite", "boat", "red"]]];
const index = invert(docs);
console.log(index.red.join(","), index.kite.join(","));
console.log(andQuery(index, "red", "kite").join(","));

