function lruRun(capacity, ops) {
  const map = new Map();
  const out = [];
  for (const op of ops) {
    if (op[0] === 'get') {
      const k = op[1];
      if (!map.has(k)) { out.push(null); continue; }
      const v = map.get(k);
      map.delete(k);
      map.set(k, v);
      out.push(v);
    } else {
      const k = op[1], v = op[2];
      if (map.has(k)) map.delete(k);
      map.set(k, v);
      if (map.size > capacity) map.delete(map.keys().next().value);
    }
  }
  return out;
}

function buildIndex(docs) {
  const index = {};
  for (const entry of docs) {
    const id = entry[0];
    for (const t of new Set(entry[1])) {
      if (!index[t]) index[t] = [];
      index[t].push(id);
    }
  }
  for (const t of Object.keys(index)) index[t].sort((a, b) => a - b);
  return index;
}

function searchAll(index, terms) {
  if (terms.length === 0) return [];
  let acc = index[terms[0]] ? index[terms[0]].slice() : [];
  for (let i = 1; i < terms.length; i++) {
    const list = index[terms[i]] || [];
    const keep = new Set(list);
    acc = acc.filter(function (id) { return keep.has(id); });
  }
  return acc.slice().sort((a, b) => a - b);
}

function minStackRun(ops) {
  const main = [], mins = [], out = [];
  for (const op of ops) {
    if (op[0] === 'push') {
      const v = op[1];
      main.push(v);
      if (mins.length === 0 || v <= mins[mins.length - 1]) mins.push(v);
      else mins.push(mins[mins.length - 1]);
    } else if (op[0] === 'pop') {
      if (main.length > 0) { main.pop(); mins.pop(); }
    } else {
      out.push(mins.length === 0 ? null : mins[mins.length - 1]);
    }
  }
  return out;
}

function topKFrequent(items, k) {
  const counts = new Map();
  const firstAt = new Map();
  for (let i = 0; i < items.length; i++) {
    const v = items[i];
    counts.set(v, (counts.get(v) || 0) + 1);
    if (!firstAt.has(v)) firstAt.set(v, i);
  }
  const distinct = Array.from(counts.keys());
  distinct.sort(function (a, b) {
    if (counts.get(b) !== counts.get(a)) return counts.get(b) - counts.get(a);
    return firstAt.get(a) - firstAt.get(b);
  });
  return distinct.slice(0, k);
}

