function lruEvictions(capacity, keys) {
  const map = new Map();
  const evicted = [];
  for (const k of keys) {
    if (map.has(k)) map.delete(k);
    map.set(k, true);
    if (map.size > capacity) {
      const oldest = map.keys().next().value;
      map.delete(oldest);
      evicted.push(oldest);
    }
  }
  return evicted;
}

function searchAny(index, terms) {
  const seen = new Set();
  for (const t of terms) {
    const list = index[t] || [];
    for (const id of list) seen.add(id);
  }
  return Array.from(seen).sort((a, b) => a - b);
}

